from itertools import product

def check_good_sequence(N, A_tuple, B_tuple):
    """
    Checks if sequences A and B satisfy the structural requirements for a good sequence.
    A_tuple = (a_0, ..., a_N), B_tuple = (b_0, ..., b_N)
    """
    # Check degree constraints (Sum constraints)
    sum_A = sum(A_tuple)
    sum_B = sum(B_tuple)
    if sum_A != N + 1 or sum_B != N + 1:
        return False

    # Check Condition 1: M_A = Multiset({k repeated b_k times})
    multiset_A = {}
    for a in A_tuple:
        multiset_A[a] = multiset_A.get(a, 0) + 1

    multiset_RHS1 = {}
    for k in range(N + 1):
        b_k = B_tuple[k]
        if b_k > 0:
            multiset_RHS1[k] = multiset_RHS1.get(k, 0) + b_k

    if multiset_A != multiset_RHS1:
        return False

    # Check Condition 2: M_B = Multiset({k repeated a_k times})
    multiset_B = {}
    for b in B_tuple:
        multiset_B[b] = multiset_B.get(b, 0) + 1

    multiset_RHS2 = {}
    for k in range(N + 1):
        a_k = A_tuple[k]
        if a_k > 0:
            multiset_RHS2[k] = multiset_RHS2.get(k, 0) + a_k

    if multiset_B != multiset_RHS2:
        return False

    return True

